/**
 * Fightcord rank icons -- our own badges for E / D / C / B / A / S and "unknown"
 *
 * Fightcade draws ranks from its pictures static/ranks/rank0-6.png, and Fightcord's badges
 * (fc.ui.tag, the member list's group headers, the VS screen...) use the same files. With this on:
 *   - one CSS rule shows our icon in place of every one of those pictures, Fightcade's own included
 *   - fc.data.rankImg() hands out our icons, so Fightcord's badges get them directly
 *   - the rank colours (names, tags, the VS halves) follow the icons: S red, A gold, B purple...
 *   - the emulator's in-match bar gets them too (emu-skin writes rank0-6.png, 38x38, backed up)
 * Off: everything is Fightcade's again.
 *
 * The icons live in this file (the updater only ships .js): node tools/rank-icons.js rebuilds the
 * ICONS line from assets/ranks/rank<n>@128.webp.
 */
'use strict';

let fc = null;
let store = null, cfg = null;            // rank-icons-config.json
const N_ = (s) => s;

// 0 = unknown, 1-6 = E D C B A S (Fightcade's rank numbers)
// ICONS-START (generated by tools/rank-icons.js, don't edit by hand)
const ICONS = {"0":"","1":"","2":"","3":"","4":"","5":"","6":""};
// ICONS-END
// ours are wider than tall: Fightcord's badges get a little more room by default (an explicit size stays)
const BIGGER = '.fc-tag { width: var(--sz, 22px); height: var(--sz, 22px); } .fc-tag > img { object-fit: contain; }';
// the icons' own colours, a touch lighter for text on dark
const COLORS = { E: '#c4825e', D: '#72c482', C: '#62a0ff', B: '#ad86ee', A: '#f0c14b', S: '#f5484d' };

/* ================================================================ pure parts */

const url = (n) => ICONS[n] ? 'data:image/webp;base64,' + ICONS[n] : '';

// every Fightcade rank picture (any path that ends in ranks/rank<n>.png) shows ours instead
function css() {
    return Object.keys(ICONS).map(n =>
        `img[src$="ranks/rank${n}.png"], img[src*="ranks/rank${n}.png?"] { content: url("${url(n)}"); object-fit: contain; }`).join('\n');
}

module.exports = {
    id: 'rank-icons', name: 'Rank icons',
    start: (f) => start(f),
    ICONS, COLORS, url, css
};

/* ================================================================== browser */

let saved = null;                        // Fightcade's colours and rankImg, to put back

function apply(on) {
    const d = fc.data;
    if (on && !saved) {
        saved = { colors: Object.assign({}, d.RANK_COLOR), rankImg: d.rankImg };
        Object.assign(d.RANK_COLOR, COLORS);
        d.rankImg = (r) => url(d.rankNum(r)) || saved.rankImg(r);
        fc.ui.style('fcRankIcons', css() + '\n' + BIGGER);
    } else if (!on && saved) {
        Object.assign(d.RANK_COLOR, saved.colors);
        d.rankImg = saved.rankImg;
        saved = null;
        fc.ui.style('fcRankIcons', null);
    } else return;
    fc.emit('ranks:changed', { on: !!on });
}

// 38x38 PNGs for the emulator's bar (emu-skin asks; null when off)
let emuCache = null;
async function emuFiles(size) {
    if (!cfg.enabled || !Object.keys(ICONS).length) return null;
    const s = size || 38;
    if (emuCache && emuCache.size === s) return emuCache.files;
    const files = {};
    for (const n of Object.keys(ICONS)) {
        const im = new Image();
        im.src = url(n);
        await im.decode();
        const c = document.createElement('canvas');
        c.width = c.height = s;
        const g = c.getContext('2d');
        g.imageSmoothingQuality = 'high';
        g.drawImage(im, 0, 0, s, s);
        files['rank' + n + '.png'] = Buffer.from(c.toDataURL('image/png').split(',')[1], 'base64');
    }
    emuCache = { size: s, files };
    return files;
}

function previewHtml(d) {
    if (!Object.keys(ICONS).length) return '';
    const cells = [[6, 'S'], [5, 'A'], [4, 'B'], [3, 'C'], [2, 'D'], [1, 'E'], [0, '?']]
        .map(([n, l]) => `<span class="fcriCell"><img src="${url(n)}" alt="${l}"><b>${l}</b></span>`).join('');
    return `<div class="fcriPrev${d.enabled ? ' on' : ''}"><div class="fcriRow">${cells}</div></div>`;
}

const STYLE = `
.fcriPrev { display: flex; padding: 10px 0 4px; }
.fcriRow { display: flex; flex-wrap: wrap; }
.fcriCell { display: flex; flex-direction: column; align-items: center; width: 58px; margin: 0 6px 6px 0; padding: 8px 0 6px; border-radius: 8px; background: rgba(0,0,0,.18); }
.fcriCell img { width: 40px; height: 40px; object-fit: contain; }
.fcriCell b { margin-top: 4px; font-size: 12px; color: var(--fc-muted); }
.fcriPrev:not(.on) .fcriCell img { filter: grayscale(1); opacity: .55; }
`;

function start(f) {
    fc = f;
    store = fc.config('rank-icons', { enabled: true });
    cfg = store.data;
    fc.ui.style('fcriStyle', STYLE);
    fc.own(() => { apply(false); fc.ui.style('fcriStyle', null); });
    apply(cfg.enabled);
    fc.settings.block({
        id: 'rank-icons', section: 'appearance', title: 'Rank icons', hint: '— the badges for S, A, B, C, D, E', store, order: 15,
        fields: [
            { key: 'enabled', type: 'switch', label: 'Fightcord rank icons',
                hint: 'Everywhere ranks show, the in-match bar included, with names in the icons’ colours. Off = Fightcade’s own.',
                onChange: (v) => { emuCache = null; apply(!!v); fc.settings.refresh('rank-icons'); } },
            { type: 'html', id: 'rank-icons-preview', html: previewHtml }
        ]
    });
    return api;
}

const api = {
    enabled: () => !!(cfg && cfg.enabled),
    emuFiles: (size) => emuFiles(size),
    url: (n) => url(n)
};
Object.keys(api).forEach(k => Object.defineProperty(module.exports, k, Object.getOwnPropertyDescriptor(api, k)));
